<script setup lang="ts">
import{ref,onMounted}from'vue';import{request}from'../api/client'
const source=ref('postgres'),tables=ref<Array<{name:string;estimatedRows:number}>>([]),table=ref(''),page=ref(1),total=ref(0),rows=ref<Array<Record<string,unknown>>>([]),busy=ref(false),error=ref(''),pattern=ref('*'),cursor=ref('0'),nextCursor=ref('0'),keyDetail=ref<Record<string,unknown>|null>(null),dialog=ref(false)
async function load(){busy.value=true;error.value='';try{if(source.value==='postgres'){if(!tables.value.length)tables.value=await request('/data/postgres/tables');if(!table.value)table.value=tables.value[0]?.name??'';if(table.value){const out=await request<{items:typeof rows.value;total:number}>(`/data/postgres/tables/${encodeURIComponent(table.value)}?page=${page.value}&pageSize=25`);rows.value=out.items;total.value=out.total}}else{const out=await request<{items:typeof rows.value;cursor:string;total:number}>(`/data/redis/keys?cursor=${cursor.value}&pattern=${encodeURIComponent(pattern.value)}`);rows.value=out.items;nextCursor.value=out.cursor;total.value=out.total}}catch(e){error.value=e instanceof Error?e.message:'数据读取失败'}finally{busy.value=false}}
function change(){page.value=1;cursor.value='0';rows.value=[];load()}
async function detail(row:Record<string,unknown>){try{keyDetail.value=source.value==='redis'?await request(`/data/redis/value?key=${encodeURIComponent(String(row.key))}`):row;dialog.value=true}catch(e){error.value=e instanceof Error?e.message:'详情不可用'}}
onMounted(load)
</script>
<template><section class="page-heading"><div><h1>数据库浏览</h1><p>管理员只读视图，敏感字段、签名URL和二进制已隐藏。不提供SQL或Redis写入命令。</p></div><el-button :loading="busy" @click="load">刷新数据</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel section-gap data-controls"><el-radio-group v-model="source" aria-label="数据库来源" @change="change"><el-radio-button value="postgres">PostgreSQL</el-radio-button><el-radio-button value="redis">Redis</el-radio-button></el-radio-group><el-select v-if="source==='postgres'" v-model="table" aria-label="PostgreSQL数据表" filterable @change="change"><el-option v-for="t in tables" :key="t.name" :label="t.name" :value="t.name"/></el-select><template v-else><el-input v-model="pattern" aria-label="Redis键筛选" placeholder="* 或 media-tool:*" @keyup.enter="change"/><el-button @click="change">筛选键</el-button></template><span class="muted">{{total}} {{source==='postgres'?'行':'个键'}}</span></section><section v-loading="busy" class="panel"><div class="data-rows"><button v-for="(row,index) in rows" :key="index" class="data-row" @click="detail(row)"><span>{{source==='redis'?row.key:`第 ${(page-1)*25+index+1} 行`}}</span><pre>{{JSON.stringify(row,null,2)}}</pre><small>查看格式化详情</small></button></div><el-empty v-if="!busy&&!rows.length" description="当前表或游标页没有数据"/><el-pagination v-if="source==='postgres'" v-model:current-page="page" :page-size="25" :total="total" layout="prev,pager,next,total" @current-change="load"/><el-button v-else :disabled="nextCursor==='0'" @click="cursor=nextCursor;load()">下一游标页</el-button></section><el-dialog v-model="dialog" title="只读格式化数据" width="min(900px,95vw)"><pre class="data-detail">{{JSON.stringify(keyDetail,null,2)}}</pre><template #footer><el-button @click="dialog=false">关闭</el-button></template></el-dialog></template>
<style scoped>.data-controls{display:flex;flex-wrap:wrap;gap:16px;align-items:center}.data-controls .el-select{width:340px;max-width:100%}.data-controls .el-input{max-width:350px}.data-rows{display:grid;gap:16px}.data-row{text-align:left;background:var(--page-bg,#f5f7f8);padding:16px;border:1px solid var(--border);border-radius:6px;color:var(--text)}.data-row span{font-weight:600;overflow-wrap:anywhere}.data-row pre{max-height:200px;overflow:auto;font-size:12px}.data-row small{color:var(--el-color-primary)}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.data-detail{max-height:65dvh;overflow:auto}.el-pagination{margin-top:24px;overflow:auto}</style>
